content.text:
            uri, is_tel, j = parse_address(p, 0, len(p))
            if j != len(p):
                raise Reject("fields")
            items.append((uri, is_tel))
    cnt = len(items)
    if cnt < 1 or cnt > 2:
        raise Reject("fields")
    if cnt == 2:
        if items[0][1] == items[1][1]:
            raise Reject("fields")
        if items[0][1]:
            items = [items[1], items[0]]
    return [items[0][0]] if cnt == 1 else [items[0][0], items[1][0]]


def parse_privacy(rows):
    if rows is None:
        return "absent"
    seen = None
    for row in rows:
        for part in row.split(";"):
            it = part.strip(_OWS).lower()
            if it != "id" and it != "none":
                raise Reject("fields")
            if seen is None:
                seen = it
            elif seen != it:
                raise Reject("fields")
    if seen is None:
        raise Reject("fields")
    return seen


def parse_cseq(v, method):
    n = len(v)
    i = 0
    while i < n and v[i] in _DIGITS:
        i += 1
    if i < 1 or i > 10:
        raise Reject("fields")
    val = int(v[:i])
    if val < 1 or val > 2147483647:
        raise Reject("fields")
    j = _skip_ows(v, i, n)
    if j == i:
        raise Reject("fields")
    if v[j:] != method:
        raise Reject("fields")
    return val


# --------------------------------------------------------------------------
# Wire parsing (section 3)
# --------------------------------------------------------------------------

def parse_request(data):
    if len(data) > REQ_BODY_MAX:
        raise Reject("syntax")
    idx = data.find(b"\r\n\r\n")
    if idx < 0:
        raise Reject("syntax")
    hblock = data[:idx]
    body = data[idx + 4:]
    if len(hblock) > HDR_BLOCK_MAX:
        raise Reject("syntax")
    if not HDRBYTES_RE.fullmatch(hblock.replace(b"\r\n", b"")):
        raise Reject("syntax")
    lines = hblock.decode("ascii").split("\r\n")
    if len(lines) - 1 > HDR_LINES_MAX:
        raise Reject("syntax")
    for ln in lines:
        if len(ln) > LINE_MAX:
            raise Reject("syntax")

    start = lines[0].split(" ")
    if len(start) != 3:
        raise Reject("syntax")
    method = start[0]
    if method != "INVITE" and method != "MESSAGE":
        raise Reject("syntax")
    if start[2] != "SIP/2.0":
        raise Reject("syntax")
    target = canon_sip(start[1])
    if target is None:
        raise Reject("syntax")

    fields = []
    prev = None
    for ln in lines[1:]:
        c0 = ln[:1]
        if c0 == " " or c0 == "\t":
            if prev is None:
                raise Reject("syntax")
            prev[1] = prev[1].rstrip(_OWS) + " " + ln.lstrip(_OWS)
            continue
        colon = ln.find(":")
        if colon < 0:
            raise Reject("syntax")
        name = ln[:colon].rstrip(_OWS)
        if not name or not NAME_RE.fullmatch(name):
            raise Reject("syntax")
        name = name.lower()
        name = COMPACT.get(name, name)
        prev = [name, ln[colon + 1:]]
        fields.append(prev)

    groups = {}
    for name, value in fields:
        value = value.strip(_OWS)
        g = groups.get(name)
        if g is None:
            groups[name] = [value]
        else:
            g.append(value)

    for req in SINGLETONS:
        g = groups.get(req)
        if g is None or len(g) != 1:
            raise Reject("headers")

    cl = groups["content-length"][0]
    if not CL_RE.fullmatch(cl) or int(cl) != len(body):
        raise Reject("length")

    from_uri, tag = parse_from(groups["from"][0])
    to_uri = parse_to(groups["to"][0])
    if to_uri != target:
        raise Reject("fields")
    call_id = groups["call-id"][0]
    if not CALLID_RE.fullmatch(call_id):
        raise Reject("fields")
    cseq = parse_cseq(groups["cseq"][0], method)
    pai = parse_identity(groups.get("p-asserted-identity"))
    ppi = parse_identity(groups.get("p-preferred-identity"))
    privacy = parse_privacy(groups.get("privacy"))

    return {
        "method": method,
        "target": target,
        "body": body,
        "from_uri": from_uri,
        "tag": tag,
        "call_id": call_id,
        "cseq": cseq,
        "pai": pai,
        "ppi": ppi,
        "privacy": privacy,
    }


